const CONFIG = {
  supabaseUrl: "https://hsaomakvlfrpfihuaexg.supabase.co",
  emailDono: "SEU_EMAIL@gmail.com",
  siteUrl: "https://salva-vendas.vercel.app",
  webhookUrl: "https://veltorati.app.n8n.cloud/webhook",
  stripeEssencial: "https://buy.stripe.com/SEU_LINK_29",
  stripeDestaque: "https://buy.stripe.com/SEU_LINK_49"
};
const rota = $("Novo Pedido").isExecuted ? "novo" : $("Abrir Aprovação").isExecuted ? "abrir" : "confirmar";
const entrada = $input.first().json;
return [{ json: { ...CONFIG, rota, query: entrada.query || {}, body: entrada.body || {} } }];

const dados = $input.first().json;
if (dados.rota !== "novo") return [];
const id = String(dados.body.id || "");
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) return [];
return [{ json: {
  url: `${dados.supabaseUrl}/rest/v1/pedidos?id=eq.${id}&notificado_em=is.null`,
  patch: { notificado_em: new Date().toISOString() }
} }];

const config = $("Configuração").first().json;
const pedido = $input.first().json;
if (!pedido.id) return [];
const limpar = (texto) => String(texto ?? "").replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const loja = pedido.loja;
const destaque = pedido.plano === "destaque";
const preco = destaque ? "49€" : "29€";
const stripe = destaque ? config.stripeDestaque : config.stripeEssencial;
const referencia = pedido.id.slice(0, 8).toUpperCase();
const aprovar = `${config.webhookUrl}/montra-aprovar?id=${pedido.id}&token=${pedido.token}`;
const previa = loja.products.map((a) => `<li>${limpar(a.name)}: ${a.oldPrice}€ → <b>${a.promoPrice}€</b> (<a href="${config.supabaseUrl}/storage/v1/object/public/montras/${a.photo}">foto</a>)</li>`).join("");
const pagamento = stripe.includes("SEU_LINK")
  ? "<p>Vamos enviar-lhe as instruções de pagamento.</p>"
  : `<p>Se ainda não pagou, conclua aqui: <a href="${stripe}?prefilled_email=${encodeURIComponent(pedido.email)}">pagar ${preco}</a>.</p>`;

return [{ json: {
  donoPara: config.emailDono,
  donoAssunto: `Novo pedido ${referencia}: ${loja.storeName} (${preco})`,
  donoHtml: `<h2>Novo pedido de montra</h2>
<p><b>${limpar(loja.storeName)}</b><br>Pacote: ${pedido.plano} (${preco})<br>Email: ${limpar(pedido.email)}<br>WhatsApp: <a href="https://wa.me/${loja.whatsappNumber}">${loja.whatsappNumber}</a><br>Referência: ${referencia}</p>
<ol>${previa}</ol>
<p><b>Confirme o pagamento na Stripe antes de aprovar.</b></p>
<p><a href="${aprovar}" style="display:inline-block;padding:14px 22px;background:#22C55E;color:#04210F;font-weight:bold;border-radius:8px;text-decoration:none">Rever e aprovar montra</a></p>`,
  clientePara: pedido.email,
  clienteAssunto: `Recebemos o seu pedido (${referencia})`,
  clienteHtml: `<p>Olá!</p><p>Recebemos o pedido da montra da <b>${limpar(loja.storeName)}</b>, pacote ${pedido.plano} (${preco}).</p>${pagamento}<p>Depois de confirmado o pagamento, enviamos o link da montra em menos de 30 minutos.</p>`
} }];

const dados = $input.first().json;
if (dados.rota !== "abrir") return [];
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const valido = uuid.test(dados.query.id) && uuid.test(dados.query.token);
const conteudo = valido
  ? `<h2>Aprovar montra ${dados.query.id.slice(0, 8).toUpperCase()}</h2><p>Confirmou o pagamento na Stripe?</p><form method="post" action=""><button style="padding:16px 26px;background:#22C55E;border:0;border-radius:10px;font-size:17px;font-weight:bold">Sim, aprovar e enviar ao lojista</button></form>`
  : "<h2>Ligação inválida</h2>";
return [{ json: { html: `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:sans-serif;text-align:center;padding:40px 16px">${conteudo}</body>` } }];

const dados = $input.first().json;
if (dados.rota !== "confirmar") return [];
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const nulo = "00000000-0000-0000-0000-000000000000";
const id = uuid.test(dados.query.id) ? dados.query.id : nulo;
const token = uuid.test(dados.query.token) ? dados.query.token : nulo;
return [{ json: {
  url: `${dados.supabaseUrl}/rest/v1/pedidos?id=eq.${id}&token=eq.${token}&estado=eq.pendente`,
  patch: { estado: "aprovado", aprovado_em: new Date().toISOString() }
} }];

const config = $("Configuração").first().json;
const pedido = $input.first().json;
const pagina = (conteudo) => `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:sans-serif;text-align:center;padding:40px 16px">${conteudo}</body>`;

if (!pedido.id) {
  return [{ json: { aprovado: false, html: pagina("<h2>Nada para aprovar</h2><p>Este pedido já foi aprovado ou a ligação é inválida.</p>") } }];
}

const limpar = (texto) => String(texto ?? "").replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const loja = pedido.loja;
const link = `${config.siteUrl}/template-base.html?loja=${pedido.id}`;
const nome = loja.storeName;
const melhor = Math.max(...loja.products.map((a) => Math.floor((1 - a.promoPrice / a.oldPrice) * 100 + 1e-9)));
const textos = [
  ["Abertura", `⚡ BLACK FRIDAY na ${nome}! Descontos até ${melhor}% por tempo limitado. Veja a montra e encomende pelo WhatsApp: ${link}`],
  ["Stories do Instagram", `🔥 A nossa montra de Black Friday está no ar. Toque no link, escolha o seu artigo e encomende em segundos: ${link}`],
  ["Lembrete", `⏰ O cronómetro está a contar! As ofertas da ${nome} terminam em breve. Dê uma vista de olhos: ${link}`]
];
if (pedido.plano === "destaque") {
  textos.push(
    ["Stock", `👀 Há artigos a esgotar na ${nome}. Garanta o seu antes que acabe: ${link}`],
    ["Última chamada", `🚨 Última chamada de Black Friday! Encomende agora na ${nome}: ${link}`]
  );
  const horas = ["09h00", "12h30", "15h00", "18h00", "21h00"];
  const ordem = [0, 1, 3, 2, 4];
  const agenda = ordem.map((indice, posicao) => [`${horas[posicao]} · ${textos[indice][0]}`, textos[indice][1]]);
  textos.splice(0, textos.length, ...agenda);
}
const blocos = textos.map(([titulo, texto]) => `<h3>${limpar(titulo)}</h3><p style="padding:12px;background:#f4f4f5;border-radius:8px">${limpar(texto)}</p>`).join("");
const mensagem = `Olá! A sua montra de Black Friday já está online: ${link}`;

return [{ json: {
  aprovado: true,
  html: pagina(`<h2>✅ Montra aprovada</h2><p><a href="${link}">${link}</a></p><p><a href="https://wa.me/${loja.whatsappNumber}?text=${encodeURIComponent(mensagem)}">Enviar também por WhatsApp</a></p>`),
  clientePara: pedido.email,
  clienteAssunto: "A sua montra de Black Friday está online 🎉",
  clienteHtml: `<p>Olá!</p><p>A montra da <b>${limpar(nome)}</b> já está online:</p><p><a href="${link}">${link}</a></p><h2>Textos prontos a publicar</h2>${blocos}<p>Boas vendas!</p>`,
  donoPara: config.emailDono,
  donoAssunto: `Montra entregue: ${nome}`,
  donoHtml: `<p>Montra aprovada e enviada para ${limpar(pedido.email)}.</p><p><a href="${link}">${link}</a></p>`
} }];
